///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name selectBox
 * @description select Box 처리
 * @returns {void}
 * @hidden N
 */
scwin.selectBox = function () {
    const date = new Date();
    let year;
    document.write("<option value=''>--- 선택 ---</option>");
    for (let i = 0; i <= 10; i++) {
        year = date.getFullYear();
        document.write("<option value='" + year + "' >" + year + "년</option>");
        date.setYear(date.getFullYear() + 1);
    }
    document.write("<option value='완료'>완료</option>");
    document.write("<option value='미정'>미정</option>");
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function () {
    const frm = (document.searchListForm || { elements: [] });
    if (!(await (async (c) => { const raw = String((c && c.getValue) ? (c.getValue() ?? "") : ""); if (raw.length === 0) { return true; } const v = raw.split("-").join("").split("/").join(""); if (c && c.setValue) { c.setValue(v); } const lbl = "기술이전 계약일"; const lp = lbl ? (lbl + ": ") : ""; if (v.length !== 8) { await $c.win.alert(lp + "날짜는 8 자리 YYYYMMDD 형식입니다."); if (c && c.focus) { c.focus(); } return false; } let digits = true; for (let i = 0; i < v.length; i++) { const ch = v.charAt(i); if (ch < "0" || ch > "9") { digits = false; break; } } if (!digits) { await $c.win.alert(lp + "숫자만 입력가능합니다."); if (c && c.focus) { c.focus(); } return false; } const mm = Number(v.substring(4, 6)); if (mm > 12 || mm < 1) { await $c.win.alert(lp + "달은 1 에서 12 사이여야 합니다."); if (c && c.focus) { c.focus(); } return false; } if (!$c.date.checkCalendarFormat(c, "yyyyMMdd", { clearOnInvalid: false })) { await $c.win.alert(lp + " 존재하지 않는 날짜입니다."); if (c && c.focus) { c.focus(); } return false; } return true; })($c.util.getComponent('cal_techTransContrtDd')))) {
        return false;
    }
    const vFields = {};
    vFields["ipt_pipelineNm"] = { required: true };
    vFields["ipt_clncindContn"] = { required: true };
    vFields["ipt_clncCntrNm"] = { required: true };
    vFields["cal_techTransContrtDd"] = { format: 'date' };
    const result = await $c.validate.validateDataCollect($c.util.getComponent("form_2"), { validateType: 'alert', checkType: 'single', focus: true, fields: vFields });
    if (!result) {
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name loadForm
 * @description load Form 처리
 * @param {*} listBzSeq listBzSeq
 * @param {String} ipt_pipelineNm ipt_pipelineNm
 * @param {*} ipt_clncindContn ipt_clncindContn
 * @param {String} ipt_clncCntrNm ipt_clncCntrNm
 * @param {String} ipt_clncApprovInstNm ipt_clncApprovInstNm
 * @param {*} ipt_clncStepContn ipt_clncStepContn
 * @param {*} clncEndSchdlYy clncEndSchdlYy
 * @param {String} ipt_techTransObjLocalNm ipt_techTransObjLocalNm
 * @param {String} ipt_techTransCtpartNm ipt_techTransCtpartNm
 * @param {String} cal_techTransContrtDd cal_techTransContrtDd
 * @param {*} ipt_techTransContrtTotamt ipt_techTransContrtTotamt
 * @param {*} ipt_techTransContrtAmt ipt_techTransContrtAmt
 * @param {*} ipt_techTransRcvAmt ipt_techTransRcvAmt
 * @param {*} ipt_remk ipt_remk
 * @returns {void}
 * @hidden N
 */
scwin.loadForm = function (listBzSeq, ipt_pipelineNm, ipt_clncindContn, ipt_clncCntrNm, ipt_clncApprovInstNm, ipt_clncStepContn, clncEndSchdlYy, ipt_techTransObjLocalNm, ipt_techTransCtpartNm, cal_techTransContrtDd, ipt_techTransContrtTotamt, ipt_techTransContrtAmt, ipt_techTransRcvAmt, ipt_remk) {
    // TODO Stage2(규칙19): fieldEl(DOM 요소 계약) → 컴포넌트 getValue/setValue 계약으로 전환 필요
    $c.util.getComponent('dma_registerReq').set('listBzSeq', listBzSeq);
