};

/**
 * @method
 * @name removeChar
 * @description remove Char 처리
 * @param {*} org org
 * @param {*} ch ch
 * @returns {void}
 * @hidden N
 */
scwin.removeChar = function (org, ch) {

    const len = org.length;
    let returnStr = '';

    for (i=0; i<len; i++){
        if (org.charAt(i) === ch)
        continue;
        returnStr += org.charAt(i);
    }

    return returnStr;
};

